function important_page_setting_key(string $slug, string $field): string
{
    return 'important_page_' . str_replace('-', '_', $slug) . '_' . $field;
}

function important_page_title(string $slug): string
{
    $catalog = important_page_catalog();
    $fallback = $catalog[$slug]['title'] ?? 'Important Page';
    return app_setting(important_page_setting_key($slug, 'title'), $fallback);
}

function important_page_body(string $slug): string
{
    return app_setting(important_page_setting_key($slug, 'body'), important_page_default_body($slug));
}
